package com.example.sgva.domain

/**
 * Reglas de formato compartidas por las entidades del dominio. Centraliza la
 * verificación del formato `AAAAS` para que `Estudiante.cohorte` y
 * `Docente.periodo` apliquen exactamente el mismo criterio.
 */
internal object ReglasDeFormato {

    /** Regex de referencia definida en `DESIGN_SGVA.md`, Sección 0.1. */
    private val PATRON_PERIODO_ACADEMICO = Regex("""^\d{4}[12]$""")

    /**
     * Verifica que [valor] cumpla el formato `AAAAS` y lo devuelve sin cambios.
     *
     * @throws FormatoPeriodoInvalidoException si el formato no es válido.
     */
    fun exigirPeriodoAcademico(valor: String, campo: String): String {
        if (!PATRON_PERIODO_ACADEMICO.matches(valor)) {
            throw FormatoPeriodoInvalidoException(campo, valor)
        }
        return valor
    }

    /**
     * Verifica que [valor] no esté vacío ni en blanco y lo devuelve sin cambios.
     *
     * @throws CampoRequeridoVacioException si el valor está en blanco.
     */
    fun exigirNoVacio(valor: String, campo: String): String {
        if (valor.isBlank()) {
            throw CampoRequeridoVacioException(campo)
        }
        return valor
    }

    /** Tolerancia numérica para las sumas de ponderaciones (`DESIGN_SGVA.md` §0.1). */
    const val TOLERANCIA_SUMA_PONDERACIONES: Double = 0.001

    /**
     * Verifica que [valor] no sea negativo y lo devuelve sin cambios. Aplica a
     * todo peso del modelo de ponderaciones (factores, características y
     * mezcla encuestas/documental; `DESIGN_SGVA.md` §0.1).
     *
     * @throws PonderacionNegativaException si [valor] es negativo.
     */
    fun exigirPonderacionNoNegativa(valor: Double, contexto: String): Double {
        if (valor < 0.0) {
            throw PonderacionNegativaException(contexto, valor)
        }
        return valor
    }

    /**
     * Verifica que [suma] sea igual a `1.0` dentro de
     * [TOLERANCIA_SUMA_PONDERACIONES] y la devuelve sin cambios.
     *
     * @throws SumaPonderacionesInvalidaException si [suma] se aleja de `1.0` más que la tolerancia.
     */
    fun exigirSumaUno(suma: Double, contexto: String): Double {
        if (kotlin.math.abs(suma - 1.0) > TOLERANCIA_SUMA_PONDERACIONES) {
            throw SumaPonderacionesInvalidaException(contexto, suma)
        }
        return suma
    }
}

package com.example.sgva.domain

/**
 * Puerto de salida (Outbound/Driven Port) para persistir y recuperar las
 * entidades de dominio ya validadas (`DESIGN_SGVA.md` §3).
 *
 * El dominio declara la interfaz; la tecnología concreta vive en
 * `infrastructure` y nunca al revés (Inversión de Dependencia). En esta versión
 * el único adaptador es en memoria; un futuro adaptador Spring Data debe poder
 * sustituirlo sin tocar el dominio ni los casos de uso.
 *
 * Toda entidad que entra o sale de este puerto es válida por construcción: sus
 * invariantes se verifican en el bloque `init` de [Estudiante] y [Docente], no
 * aquí ni en los adaptadores (`DESIGN_SGVA.md` §0.1).
 *
 * El identificador (`id`) es la clave de identidad de cada entidad. Este puerto
 * solo almacena y consulta; la regla de aplicación "un `id` no puede
 * registrarse dos veces" la aplican los casos de uso de registro.
 */
interface AcademicDataRepository {

    /** Persiste [estudiante] indexado por su `id` y lo devuelve sin cambios. */
    fun guardarEstudiante(estudiante: Estudiante): Estudiante

    /** Devuelve el estudiante con [id], o `null` si no hay ninguno registrado. */
    fun buscarEstudiantePorId(id: String): Estudiante?

    /** Devuelve todos los estudiantes registrados, en orden de inserción. */
    fun listarEstudiantes(): List<Estudiante>

    /** Persiste [docente] indexado por su `id` y lo devuelve sin cambios. */
    fun guardarDocente(docente: Docente): Docente

    /** Devuelve el docente con [id], o `null` si no hay ninguno registrado. */
    fun buscarDocentePorId(id: String): Docente?

    /** Devuelve todos los docentes registrados, en orden de inserción. */
    fun listarDocentes(): List<Docente>

    /** Persiste [respuesta] indexada por su `id` y la devuelve sin cambios. */
    fun guardarRespuestaEncuesta(respuesta: RespuestaEncuesta): RespuestaEncuesta

    /** Devuelve la respuesta de encuesta con [id], o `null` si no hay ninguna registrada. */
    fun buscarRespuestaEncuestaPorId(id: String): RespuestaEncuesta?

    /** Devuelve todas las respuestas de encuesta registradas, en orden de inserción. */
    fun listarRespuestasEncuesta(): List<RespuestaEncuesta>
}

package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.FormatoArchivoInvalidoException
import de.siegmar.fastcsv.reader.CsvReader
import org.springframework.stereotype.Component
import java.io.ByteArrayInputStream
import java.nio.charset.StandardCharsets

/**
 * Adaptador de [com.example.sgva.domain.DocumentParserPort] para archivos `.csv`,
 * implementado sobre FastCSV (`DESIGN_SGVA.md` §4, adaptador «OpenCsvParser» del
 * diseño; se usa FastCSV por ser una dependencia sin transitivas y gestionable
 * dentro del stack de Spring Boot 4).
 *
 * Se lee la primera fila no vacía como encabezado; la normalización de los
 * valores la aplica [ParserDocumentalBase] a través de los mapeadores.
 */
@Component
internal class CsvDocumentParser : ParserDocumentalBase() {

    override fun soporta(nombreArchivo: String): Boolean = extension(nombreArchivo) == "csv"

    override fun leerTabla(contenido: ByteArray): TablaCruda {
        val registros = CsvReader.builder()
            .skipEmptyLines(true)
            .ofCsvRecord(ByteArrayInputStream(contenido), StandardCharsets.UTF_8)
            .use { lector -> lector.map { it.fields } }

        if (registros.isEmpty()) {
            throw FormatoArchivoInvalidoException("El archivo CSV no contiene ninguna fila.")
        }

        return TablaCruda(
            encabezados = registros.first().map(String::trim),
            filas = registros.drop(1),
        )
    }

    private fun extension(nombreArchivo: String): String =
        nombreArchivo.substringAfterLast('.', "").lowercase()
}

package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.Docente
import com.example.sgva.domain.DocumentParserPort
import com.example.sgva.domain.Estudiante
import com.example.sgva.domain.FormatoArchivoInvalidoException
import com.example.sgva.domain.RespuestaEncuesta

/**
 * Base común de los adaptadores de [DocumentParserPort]. Concentra el
 * *Protocolo de Validación en Origen* (`DESIGN_SGVA.md` §5):
 *
 *  1. Cada adaptador concreto solo se encarga de leer el archivo a una
 *     [TablaCruda] (encabezados + filas de texto) según su formato físico.
 *  2. Esta base verifica que estén todas las columnas obligatorias de la entidad.
 *  3. Mapea y normaliza fila por fila; cualquier fallo se envuelve en
 *     [FormatoArchivoInvalidoException] indicando el archivo y la fila, sin dejar
 *     escapar excepciones técnicas de la librería de parseo.
 */
internal abstract class ParserDocumentalBase : DocumentParserPort {

    /**
     * Lee el archivo a una tabla de texto. Puede lanzar excepciones técnicas de
     * la librería subyacente: [transformar] las traduce a excepción controlada.
     */
    protected abstract fun leerTabla(contenido: ByteArray): TablaCruda

    final override fun extraerEstudiantes(nombreArchivo: String, contenido: ByteArray): List<Estudiante> =
        transformar(nombreArchivo, contenido, MapeadorEstudiante)

    final override fun extraerDocentes(nombreArchivo: String, contenido: ByteArray): List<Docente> =
        transformar(nombreArchivo, contenido, MapeadorDocente)

    final override fun extraerRespuestasEncuestas(nombreArchivo: String, contenido: ByteArray): List<RespuestaEncuesta> =
        transformar(nombreArchivo, contenido, MapeadorRespuestaEncuesta)

    private fun <T> transformar(
        nombreArchivo: String,
        contenido: ByteArray,
        mapeador: MapeadorEntidad<T>,
    ): List<T> {
        val tabla = leerTablaControlada(nombreArchivo, contenido)
        exigirColumnas(nombreArchivo, tabla.encabezados, mapeador.columnasObligatorias)

        return tabla.filas.mapIndexed { indice, valores ->
            val numeroFila = indice + 2 // +1 por el encabezado, +1 para numeración en base 1
            val fila = tabla.encabezados.zip(valores).toMap()
            try {
                mapeador.mapear(fila)
            } catch (datoInvalido: IllegalArgumentException) {
                // Cubre también NumberFormatException (subtipo) y las excepciones de dominio.
                throw FormatoArchivoInvalidoException(
                    "Archivo '$nombreArchivo', fila $numeroFila: ${datoInvalido.message}",
                    datoInvalido,
                )
            }
        }
    }

    private fun leerTablaControlada(nombreArchivo: String, contenido: ByteArray): TablaCruda =
        try {
            leerTabla(contenido)
        } catch (formatoInvalido: FormatoArchivoInvalidoException) {
            throw formatoInvalido
        } catch (falloTecnico: Exception) {
            throw FormatoArchivoInvalidoException(
                "No se pudo leer el archivo '$nombreArchivo': ${falloTecnico.message}",
                falloTecnico,
            )
        }

    private fun exigirColumnas(
        nombreArchivo: String,
        encabezados: List<String>,
        obligatorias: Set<String>,
    ) {
        val presentes = encabezados.map { it.trim() }.toSet()
        val faltantes = (obligatorias - presentes).sorted()
        if (faltantes.isNotEmpty()) {
            throw FormatoArchivoInvalidoException(
                "Al archivo '$nombreArchivo' le faltan columnas obligatorias: ${faltantes.joinToString(", ")}.",
            )
        }
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.DocumentParserPort
import com.example.sgva.domain.EntidadDuplicadaException
import com.example.sgva.domain.FormatoArchivoInvalidoException
import com.example.sgva.domain.RegistroOmitido
import com.example.sgva.domain.ResultadoIngesta

/**
 * Orquestación común a las cargas masivas de archivo (`DESIGN_SGVA.md` §2):
 * elige el adaptador de parseo que soporta el archivo, le pide las entidades ya
 * normalizadas y válidas, y da de alta cada una. Un `id` ya existente —en el
 * repositorio o repetido dentro del propio archivo— se reporta como omitido en
 * lugar de abortar la carga completa.
 *
 * Las subclases solo aportan el detalle específico de la entidad: cómo pedírsela
 * al parser, cuál es su `id` y con qué caso de uso registrarla.
 */
abstract class ProcesarArchivoUseCase<T>(
    private val parsers: List<DocumentParserPort>,
) : IngestarArchivoUseCase {

    protected abstract fun extraer(
        parser: DocumentParserPort,
        nombreArchivo: String,
        contenido: ByteArray,
    ): List<T>

    protected abstract fun idDe(entidad: T): String

    protected abstract fun registrar(entidad: T)

    final override fun ejecutar(nombreArchivo: String, contenido: ByteArray): ResultadoIngesta {
        val parser = parsers.firstOrNull { it.soporta(nombreArchivo) }
            ?: throw FormatoArchivoInvalidoException(
                "El archivo '$nombreArchivo' no tiene un formato soportado (.csv, .xlsx).",
            )

        val entidades = extraer(parser, nombreArchivo, contenido)
        val omitidos = mutableListOf<RegistroOmitido>()
        var registrados = 0

        for (entidad in entidades) {
            try {
                registrar(entidad)
                registrados++
            } catch (duplicado: EntidadDuplicadaException) {
                omitidos += RegistroOmitido(idDe(entidad), duplicado.message ?: "registro duplicado")
            }
        }

        return ResultadoIngesta(
            nombreArchivo = nombreArchivo,
            totalRegistrosLeidos = entidades.size,
            registrados = registrados,
            omitidos = omitidos.toList(),
        )
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.Docente
import com.example.sgva.domain.DocumentParserPort

/**
 * Módulo 2 — carga masiva de la planta profesoral de un periodo desde un archivo
 * CSV o Excel (`DESIGN_SGVA.md` §2). Registra cada docente reutilizando
 * [RegistrarDocenteUseCase].
 */
class ProcesarDatosDocentesUseCase(
    parsers: List<DocumentParserPort>,
    private val registrarDocente: RegistrarDocenteUseCase,
) : ProcesarArchivoUseCase<Docente>(parsers) {

    override fun extraer(
        parser: DocumentParserPort,
        nombreArchivo: String,
        contenido: ByteArray,
    ): List<Docente> = parser.extraerDocentes(nombreArchivo, contenido)

    override fun idDe(entidad: Docente): String = entidad.id

    override fun registrar(entidad: Docente) {
        registrarDocente.ejecutar(entidad)
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.Docente
import com.example.sgva.domain.EntidadDuplicadaException

/**
 * Registra un nuevo docente de la planta profesoral (Factor 3).
 *
 * La validación de formato de los campos ya está garantizada por el bloque
 * `init` de [Docente]. Este caso de uso solo aporta la regla de aplicación
 * restante: el identificador debe ser único.
 */
class RegistrarDocenteUseCase(
    private val repositorio: AcademicDataRepository,
) {

    /**
     * Da de alta [docente] y lo devuelve tal como quedó persistido.
     *
     * @throws EntidadDuplicadaException si ya existe un docente con el mismo `id`.
     */
    fun ejecutar(docente: Docente): Docente {
        if (repositorio.buscarDocentePorId(docente.id) != null) {
            throw EntidadDuplicadaException("docente", docente.id)
        }
        return repositorio.guardarDocente(docente)
    }
}

