}

package com.example.sgva.infrastructure.parsing

import com.example.sgva.domain.FormatoArchivoInvalidoException
import org.apache.poi.ss.usermodel.Cell
import org.apache.poi.ss.usermodel.CellType
import org.apache.poi.ss.usermodel.Row
import org.apache.poi.xssf.usermodel.XSSFWorkbook
import org.springframework.stereotype.Component
import java.io.ByteArrayInputStream

/**
 * Adaptador de [com.example.sgva.domain.DocumentParserPort] para archivos `.xlsx`,
 * implementado sobre Apache POI (`DESIGN_SGVA.md` §4, adaptador «ApachePoiExcelParser»).
 *
 * Se procesa la primera hoja del libro: la primera fila es el encabezado y el
 * resto son datos. Las celdas numéricas se convierten a texto sin el `.0` que
 * añade Excel a los enteros; la normalización final la aplica [ParserDocumentalBase].
 */
@Component
internal class ExcelDocumentParser : ParserDocumentalBase() {

    override fun soporta(nombreArchivo: String): Boolean =
        nombreArchivo.substringAfterLast('.', "").lowercase() == "xlsx"

    override fun leerTabla(contenido: ByteArray): TablaCruda =
        XSSFWorkbook(ByteArrayInputStream(contenido)).use { libro ->
            if (libro.numberOfSheets == 0) {
                throw FormatoArchivoInvalidoException("El archivo Excel no contiene ninguna hoja.")
            }

            val filas = libro.getSheetAt(0).iterator().asSequence().toList()
            if (filas.isEmpty()) {
                throw FormatoArchivoInvalidoException("La primera hoja del archivo Excel está vacía.")
            }

            val encabezados = leerFila(filas.first()).map(String::trim)
            TablaCruda(
                encabezados = encabezados,
                filas = filas.drop(1)
                    .map { leerFila(it, encabezados.size) }
                    .filter { valores -> valores.any { it.isNotBlank() } },
            )
        }

    private fun leerFila(fila: Row, columnasMinimas: Int = 0): List<String> {
        val columnas = maxOf(fila.lastCellNum.toInt(), columnasMinimas)
        return (0 until columnas).map { indice ->
            valorComoTexto(fila.getCell(indice, Row.MissingCellPolicy.RETURN_BLANK_AS_NULL))
        }
    }

    private fun valorComoTexto(celda: Cell?): String = when {
        celda == null -> ""
        celda.cellType == CellType.STRING -> celda.stringCellValue.trim()
        celda.cellType == CellType.BOOLEAN -> celda.booleanCellValue.toString()
        celda.cellType == CellType.NUMERIC -> numeroComoTexto(celda.numericCellValue)
        celda.cellType == CellType.FORMULA -> when (celda.cachedFormulaResultType) {
            CellType.STRING -> celda.stringCellValue.trim()
            CellType.NUMERIC -> numeroComoTexto(celda.numericCellValue)
            CellType.BOOLEAN -> celda.booleanCellValue.toString()
            else -> ""
        }
        else -> ""
    }

    private fun numeroComoTexto(valor: Double): String =
        if (valor % 1.0 == 0.0) valor.toLong().toString() else valor.toString()
}

package com.example.sgva.application

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.Docente
import com.example.sgva.domain.Estudiante
import com.example.sgva.domain.RespuestaEncuesta

/**
 * Doble de prueba en memoria del puerto [AcademicDataRepository]. Permite
 * ejercitar los casos de uso sin depender del adaptador de infraestructura.
 * Pública (no `internal`) para poder exponerse como bean de Spring en las
 * pruebas de integración de `infrastructure.web` (`ConfiguracionCasosDeUsoDePrueba`).
 */
class RepositorioAcademicoFalso : AcademicDataRepository {

    private val estudiantes = LinkedHashMap<String, Estudiante>()
    private val docentes = LinkedHashMap<String, Docente>()
    private val respuestasEncuesta = LinkedHashMap<String, RespuestaEncuesta>()

    override fun guardarEstudiante(estudiante: Estudiante): Estudiante {
        estudiantes[estudiante.id] = estudiante
        return estudiante
    }

    override fun buscarEstudiantePorId(id: String): Estudiante? = estudiantes[id]

    override fun listarEstudiantes(): List<Estudiante> = estudiantes.values.toList()

    override fun guardarDocente(docente: Docente): Docente {
        docentes[docente.id] = docente
        return docente
    }

    override fun buscarDocentePorId(id: String): Docente? = docentes[id]

    override fun listarDocentes(): List<Docente> = docentes.values.toList()

    override fun guardarRespuestaEncuesta(respuesta: RespuestaEncuesta): RespuestaEncuesta {
        respuestasEncuesta[respuesta.id] = respuesta
        return respuesta
    }

    override fun buscarRespuestaEncuestaPorId(id: String): RespuestaEncuesta? = respuestasEncuesta[id]

    override fun listarRespuestasEncuesta(): List<RespuestaEncuesta> = respuestasEncuesta.values.toList()

    /** Vacía los tres almacenes; útil para reutilizar la misma instancia entre pruebas. */
    fun limpiar() {
        estudiantes.clear()
        docentes.clear()
        respuestasEncuesta.clear()
    }
}

package com.example.sgva.infrastructure.web

import com.example.sgva.domain.MatrizRadar
import com.example.sgva.domain.PonderacionLikert
import com.example.sgva.domain.ResultadoIngesta
import com.example.sgva.domain.RespuestaEncuesta
import com.example.sgva.usecases.CalcularPonderacionLikertUseCase
import com.example.sgva.usecases.ConsultarRespuestasEncuestaUseCase
import com.example.sgva.usecases.GenerarMatrizRadarUseCase
import com.example.sgva.usecases.ProcesarRespuestasEncuestasUseCase
import com.example.sgva.usecases.RegistrarRespuestaEncuestaUseCase
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.RestController
import org.springframework.web.multipart.MultipartFile
import java.net.URI

/**
 * Adaptador de entrada REST (Primary Adapter) del Módulo 3 (`DESIGN_SGVA.md`
 * §4): expone la carga masiva desde archivo, el registro individual y la
 * consulta de respuestas de encuesta, junto con los indicadores de percepción
 * calculados (ponderación Likert y matriz radar) que consume el Dashboard.
 * Delega toda la lógica a los casos de uso; no reimplementa reglas de negocio.
 */
@RestController
@RequestMapping("/api/encuestas")
class EncuestaController(
    private val registrarRespuestaEncuesta: RegistrarRespuestaEncuestaUseCase,
    private val consultarRespuestasEncuesta: ConsultarRespuestasEncuestaUseCase,
    private val procesarRespuestasEncuestas: ProcesarRespuestasEncuestasUseCase,
    private val calcularPonderacionLikert: CalcularPonderacionLikertUseCase,
    private val generarMatrizRadar: GenerarMatrizRadarUseCase,
) {

    @PostMapping
    fun registrar(@RequestBody respuesta: RespuestaEncuesta): ResponseEntity<RespuestaEncuesta> {
        val registrada = registrarRespuestaEncuesta.ejecutar(respuesta)
        return ResponseEntity.created(URI.create("/api/encuestas/${registrada.id}")).body(registrada)
    }

    @GetMapping
    fun listar(): List<RespuestaEncuesta> = consultarRespuestasEncuesta.listarTodas()

    @GetMapping("/{id}")
    fun buscarPorId(@PathVariable id: String): ResponseEntity<RespuestaEncuesta> =
        consultarRespuestasEncuesta.buscarPorId(id)
            ?.let { ResponseEntity.ok(it) }
            ?: ResponseEntity.notFound().build()

    @PostMapping("/archivos", consumes = ["multipart/form-data"])
    fun cargarArchivo(@RequestParam("archivo") archivo: MultipartFile): ResponseEntity<ResultadoIngesta> {
        val resultado = procesarRespuestasEncuestas.ejecutar(
            archivo.originalFilename ?: archivo.name,
            archivo.bytes,
        )
        return ResponseEntity.status(201).body(resultado)
    }

    @GetMapping("/ponderacion-likert")
    fun obtenerPonderacionLikert(@RequestParam periodo: String?): List<PonderacionLikert> =
        calcularPonderacionLikert.ejecutar(periodo)

    @GetMapping("/matriz-radar")
    fun obtenerMatrizRadar(@RequestParam periodo: String?): MatrizRadar =
        generarMatrizRadar.ejecutar(periodo)
}

