package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.EntidadDuplicadaException
import com.example.sgva.domain.RespuestaEncuesta

/**
 * Registra una nueva respuesta de encuesta de percepción (Módulo 3).
 *
 * La validación de formato y rango de los campos ya está garantizada por el
 * bloque `init` de [RespuestaEncuesta]. Este caso de uso solo aporta la regla
 * de aplicación restante: el identificador debe ser único.
 */
class RegistrarRespuestaEncuestaUseCase(
    private val repositorio: AcademicDataRepository,
) {

    /**
     * Da de alta [respuesta] y la devuelve tal como quedó persistida.
     *
     * @throws EntidadDuplicadaException si ya existe una respuesta con el mismo `id`.
     */
    fun ejecutar(respuesta: RespuestaEncuesta): RespuestaEncuesta {
        if (repositorio.buscarRespuestaEncuestaPorId(respuesta.id) != null) {
            throw EntidadDuplicadaException("respuesta de encuesta", respuesta.id)
        }
        return repositorio.guardarRespuestaEncuesta(respuesta)
    }
}

package com.example.sgva.usecases

import com.example.sgva.domain.DocumentParserPort
import com.example.sgva.domain.RespuestaEncuesta

/**
 * Módulo 3 — tabulación automatizada de los formularios de encuesta de
 * percepción cargados desde un archivo CSV o Excel (`DESIGN_SGVA.md` §2).
 * Registra cada respuesta reutilizando [RegistrarRespuestaEncuestaUseCase].
 */
class ProcesarRespuestasEncuestasUseCase(
    parsers: List<DocumentParserPort>,
    private val registrarRespuestaEncuesta: RegistrarRespuestaEncuestaUseCase,
) : ProcesarArchivoUseCase<RespuestaEncuesta>(parsers) {

    override fun extraer(
        parser: DocumentParserPort,
        nombreArchivo: String,
        contenido: ByteArray,
    ): List<RespuestaEncuesta> = parser.extraerRespuestasEncuestas(nombreArchivo, contenido)

    override fun idDe(entidad: RespuestaEncuesta): String = entidad.id

    override fun registrar(entidad: RespuestaEncuesta) {
        registrarRespuestaEncuesta.ejecutar(entidad)
    }
}

package com.example.sgva

import com.tngtech.archunit.core.importer.ClassFileImporter
import com.tngtech.archunit.lang.syntax.ArchRuleDefinition.classes
import com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses
import com.tngtech.archunit.library.GeneralCodingRules
import org.junit.jupiter.api.Test

class ArchitectureTest {

    private val classes = ClassFileImporter().importPackages("com.example.sgva")

    // =========================================================================
    // 1. REGLAS DE AISLAMIENTO Y DEPENDENCIA (CLEAN ARCHITECTURE)
    // =========================================================================
    @Test
    fun `el dominio no debe depender de capas externas ni frameworks`() {
        noClasses()
            .that().resideInAPackage("..domain..")
            .should().dependOnClassesThat()
            .resideInAnyPackage(
                "..usecases..",
                "..infrastructure..",
                "org.springframework..",
                "jakarta..",
                "javax..",
                "com.fasterxml.jackson.."
            )
            .check(classes)
    }

    @Test
    fun `los casos de uso no deben depender de infraestructura ni frameworks`() {
        noClasses()
            .that().resideInAPackage("..usecases..")
            .should().dependOnClassesThat()
            .resideInAnyPackage(
                "..infrastructure..",
                "org.springframework..",
                "jakarta..",
                "javax.."
            )
            .allowEmptyShould(true)
            .check(classes)
    }

    @Test
    fun `el dominio y los casos de uso no deben usar anotaciones de Spring`() {
        noClasses()
            .that().resideInAnyPackage("..domain..", "..usecases..")
            .should().beAnnotatedWith("org.springframework.stereotype.Component")
            .orShould().beAnnotatedWith("org.springframework.stereotype.Service")
            .orShould().beAnnotatedWith("org.springframework.beans.factory.annotation.Autowired")
            .check(classes)
    }

    // =========================================================================
    // 2. CONVENCIONES DE NOMENCLATURA
    // =========================================================================
    @Test
    fun `las clases de casos de uso deben finalizar en UseCase`() {
        classes()
            .that().resideInAPackage("..usecases..")
            .and().areNotInterfaces()
            .should().haveSimpleNameEndingWith("UseCase")
            .allowEmptyShould(true)
            .check(classes)
    }

    @Test
    fun `las interfaces de puerto en el dominio deben finalizar en Repository o Port`() {
        classes()
            .that().resideInAPackage("..domain..")
            .and().areInterfaces()
            .and().doNotHaveFullyQualifiedName("com.example.sgva.domain.DomainMarker")
            .should().haveSimpleNameEndingWith("Repository")
            .orShould().haveSimpleNameEndingWith("Port")
            .allowEmptyShould(true)
            .check(classes)
    }

    @Test
    fun `las excepciones de dominio deben finalizar en Exception`() {
        classes()
            .that().resideInAPackage("..domain..")
            .and().areAssignableTo(Throwable::class.java)
            .should().haveSimpleNameEndingWith("Exception")
            .allowEmptyShould(true)
            .check(classes)
    }

    @Test
    fun `los adaptadores rest en infraestructura deben finalizar en Controller`() {
        classes()
            .that().resideInAPackage("..infrastructure..")
            .and().areAnnotatedWith("org.springframework.web.bind.annotation.RestController")
            .should().haveSimpleNameEndingWith("Controller")
            .allowEmptyShould(true)
            .check(classes)
    }

    // =========================================================================
    // 3. BUENAS PRÁCTICAS DE CÓDIGO
    // =========================================================================
    @Test
    fun `no se debe usar la salida estandar ni de error directa (println)`() {
        NO_CLASSES_SHOULD_ACCESS_STANDARD_STREAMS.check(classes)
    }

    companion object {
        private val NO_CLASSES_SHOULD_ACCESS_STANDARD_STREAMS = GeneralCodingRules.NO_CLASSES_SHOULD_ACCESS_STANDARD_STREAMS
    }
}

