package com.example.sgva.application

import com.example.sgva.domain.Docente
import com.example.sgva.domain.EntidadDuplicadaException
import com.example.sgva.domain.NivelFormacion
import com.example.sgva.domain.TipoDedicacion
import com.example.sgva.usecases.ConsultarDocentesUseCase
import com.example.sgva.usecases.RegistrarDocenteUseCase
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows
import kotlin.test.assertEquals
import kotlin.test.assertNull

class GestionDocentesUseCaseTest {

    private val repositorio = RepositorioAcademicoFalso()
    private val registrar = RegistrarDocenteUseCase(repositorio)
    private val consultar = ConsultarDocentesUseCase(repositorio)

    @Test
    fun `registrar un docente lo hace recuperable por id`() {
        val docente = docente(id = "D-001")

        registrar.ejecutar(docente)

        assertEquals(docente, consultar.buscarPorId("D-001"))
    }

    @Test
    fun `el listado devuelve los docentes en orden de registro`() {
        val primero = docente(id = "D-001")
        val segundo = docente(id = "D-002")

        registrar.ejecutar(primero)
        registrar.ejecutar(segundo)

        assertEquals(listOf(primero, segundo), consultar.listarTodos())
    }

    @Test
    fun `registrar un id ya existente es rechazado sin sobrescribir el registro previo`() {
        val original = docente(id = "D-001", nivelFormacion = NivelFormacion.DOCTORADO)
        registrar.ejecutar(original)

        assertThrows<EntidadDuplicadaException> {
            registrar.ejecutar(docente(id = "D-001", nivelFormacion = NivelFormacion.MAESTRIA))
        }
        assertEquals(original, consultar.buscarPorId("D-001"))
    }

    @Test
    fun `consultar un id inexistente devuelve null`() {
        assertNull(consultar.buscarPorId("NO-EXISTE"))
    }

    private fun docente(
        id: String,
        nivelFormacion: NivelFormacion = NivelFormacion.MAESTRIA,
    ): Docente = Docente(
        id = id,
        facultad = "Ingeniería",
        nivelFormacion = nivelFormacion,
        dedicacion = TipoDedicacion.TIEMPO_COMPLETO,
        periodo = "20261",
    )
}

package com.example.sgva.application

import com.example.sgva.domain.DatosInsuficientesException
import com.example.sgva.domain.Docente
import com.example.sgva.domain.NivelFormacion
import com.example.sgva.domain.TipoDedicacion
import com.example.sgva.usecases.CalcularDistribucionFormacionUseCase
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows
import kotlin.test.assertEquals

class CalcularDistribucionFormacionUseCaseTest {

    private val repositorio = RepositorioAcademicoFalso()
    private val useCase = CalcularDistribucionFormacionUseCase(repositorio)

    @Test
    fun `calcula el porcentaje de cada nivel de formacion sobre el total`() {
        guardar(NivelFormacion.DOCTORADO)
        guardar(NivelFormacion.DOCTORADO)
        guardar(NivelFormacion.MAESTRIA)
        guardar(NivelFormacion.ESPECIALIZACION)

        val porNivel = useCase.ejecutar().associateBy { it.nombre }

        assertEquals(3, porNivel.size)
        assertEquals(50.0, porNivel.getValue("Distribución de Formación - DOCTORADO").valor)
        assertEquals(25.0, porNivel.getValue("Distribución de Formación - MAESTRIA").valor)
        assertEquals(25.0, porNivel.getValue("Distribución de Formación - ESPECIALIZACION").valor)
    }

    @Test
    fun `devuelve un indicador por nivel incluso con porcentaje cero, en el orden del enum`() {
        guardar(NivelFormacion.MAESTRIA)

        val indicadores = useCase.ejecutar()

        assertEquals(NivelFormacion.entries.map { it.name }, indicadores.map { it.nombre.substringAfterLast("- ") })
        assertEquals(0.0, indicadores.first { it.nombre.endsWith("DOCTORADO") }.valor)
    }

    @Test
    fun `el filtro por periodo y facultad restringe la poblacion y etiqueta el indicador`() {
        guardar(NivelFormacion.DOCTORADO, periodo = "20261", facultad = "Ingeniería")
        guardar(NivelFormacion.MAESTRIA, periodo = "20262", facultad = "Ingeniería")
        guardar(NivelFormacion.MAESTRIA, periodo = "20261", facultad = "Ciencias")

        val indicadores = useCase.ejecutar(periodo = "20261", facultad = "Ingeniería")

        assertEquals(100.0, indicadores.first { it.nombre.endsWith("DOCTORADO") }.valor)
        assertEquals("20261", indicadores.first().periodo)
        assertEquals("Ingeniería", indicadores.first().facultad)
    }

    @Test
    fun `sin docentes lanza DatosInsuficientesException`() {
        assertThrows<DatosInsuficientesException> { useCase.ejecutar(periodo = "20261") }
    }

    private fun guardar(
        nivel: NivelFormacion,
        periodo: String = "20261",
        facultad: String = "Ingeniería",
    ) {
        repositorio.guardarDocente(
            Docente(
                id = "D${contador++}",
                facultad = facultad,
                nivelFormacion = nivel,
                dedicacion = TipoDedicacion.TIEMPO_COMPLETO,
                periodo = periodo,
            ),
        )
    }

    private var contador = 1
}

package com.example.sgva.application

import com.example.sgva.domain.DatosInsuficientesException
import com.example.sgva.domain.Docente
import com.example.sgva.domain.EstadoEstudiante
import com.example.sgva.domain.Estudiante
import com.example.sgva.domain.NivelFormacion
import com.example.sgva.domain.TipoDedicacion
import com.example.sgva.usecases.CalcularCapacidadInstaladaUseCase
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.assertThrows
import kotlin.test.assertEquals

class CalcularCapacidadInstaladaUseCaseTest {

    private val repositorio = RepositorioAcademicoFalso()
    private val useCase = CalcularCapacidadInstaladaUseCase(repositorio)

    @Test
    fun `divide los matriculados entre los profesores de tiempo completo equivalente`() {
        repeat(30) { guardarEstudiante(EstadoEstudiante.MATRICULADO) }
        guardarEstudiante(EstadoEstudiante.DESERTOR) // no cuenta en el numerador

        guardarDocente(TipoDedicacion.TIEMPO_COMPLETO) // 1.0
        guardarDocente(TipoDedicacion.TIEMPO_COMPLETO) // 1.0
        guardarDocente(TipoDedicacion.MEDIO_TIEMPO) //    0.5
        guardarDocente(TipoDedicacion.CATEDRA) //         0.25  -> total 2.75 TCE

        val indicador = useCase.ejecutar()

        assertEquals("Relación Estudiante/Profesor", indicador.nombre)
        assertEquals(10.91, indicador.valor) // 30 / 2.75 = 10.9090...
        assertEquals("CONSOLIDADO", indicador.periodo)
        assertEquals("TODAS", indicador.facultad)
    }

    @Test
    fun `los filtros de periodo y facultad se aplican al numerador y al denominador`() {
        guardarEstudiante(EstadoEstudiante.MATRICULADO, facultad = "Ingeniería")
        guardarEstudiante(EstadoEstudiante.MATRICULADO, facultad = "Ingeniería")
        guardarEstudiante(EstadoEstudiante.MATRICULADO, facultad = "Ciencias")

        guardarDocente(TipoDedicacion.TIEMPO_COMPLETO, periodo = "20261", facultad = "Ingeniería")
        guardarDocente(TipoDedicacion.TIEMPO_COMPLETO, periodo = "20262", facultad = "Ingeniería")

        val indicador = useCase.ejecutar(periodo = "20261", facultad = "Ingeniería")

        assertEquals(2.0, indicador.valor) // 2 matriculados de Ingeniería / 1.0 TCE del periodo 20261
        assertEquals("20261", indicador.periodo)
        assertEquals("Ingeniería", indicador.facultad)
    }

    @Test
    fun `sin docentes lanza DatosInsuficientesException`() {
        repeat(5) { guardarEstudiante(EstadoEstudiante.MATRICULADO) }

        assertThrows<DatosInsuficientesException> { useCase.ejecutar() }
    }

    private fun guardarEstudiante(estado: EstadoEstudiante, facultad: String = "Ingeniería") {
        repositorio.guardarEstudiante(
            Estudiante(
                id = "E${contador++}",
                programa = "Ingeniería de Sistemas",
                facultad = facultad,
                cohorte = "20231",
                estado = estado,
            ),
        )
    }

    private fun guardarDocente(
        dedicacion: TipoDedicacion,
        periodo: String = "20261",
        facultad: String = "Ingeniería",
    ) {
        repositorio.guardarDocente(
            Docente(
                id = "D${contador++}",
                facultad = facultad,
                nivelFormacion = NivelFormacion.MAESTRIA,
                dedicacion = dedicacion,
                periodo = periodo,
            ),
        )
    }

    private var contador = 1
}

